        public static IEnumerable<KeyValuePair<string,string>> FilesFor(string programTypeFolder)
        {
            string prefix = programTypeFolder.TrimEnd('/') + "/";
            foreach (KeyValuePair<string,string> pair in Data)
                if (pair.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                    yield return new KeyValuePair<string,string>(pair.Key.Substring(prefix.Length), pair.Value);
        }
    }
